const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.0/bim_models',
  qs: {
    project_id: 'SOME_INTEGER_VALUE',
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE',
    view: 'SOME_STRING_VALUE',
    'filters[id]': 'SOME_ARRAY_VALUE',
    'filters[bim_file_id]': 'SOME_INTEGER_VALUE',
    'filters[has_revisions]': 'SOME_BOOLEAN_VALUE',
    'filters[search]': 'SOME_STRING_VALUE',
    sort: 'SOME_STRING_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/bim_models?project_id=SOME_INTEGER_VALUE&page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE&view=SOME_STRING_VALUE&filters%5Bid%5D=SOME_ARRAY_VALUE&filters%5Bbim_file_id%5D=SOME_INTEGER_VALUE&filters%5Bhas_revisions%5D=SOME_BOOLEAN_VALUE&filters%5Bsearch%5D=SOME_STRING_VALUE&sort=SOME_STRING_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

const request = require('request');

const options = {
  method: 'POST',
  url: 'https://api.procore.com/rest/v1.0/bim_models',
  headers: {'content-type': 'application/json'},
  body: {
    project_id: 126,
    view: 'compact',
    bim_model: {title: 'Combined Model', auto_publish: false}
  },
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/bim_models"),
    Content = new StringContent("{\"project_id\":126,\"view\":\"compact\",\"bim_model\":{\"title\":\"Combined Model\",\"auto_publish\":false}}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
